import React, { useState } from "react";

function Login() {
  const [isLogin, setIsLogin] = useState(true);

  const [form, setForm] = useState({
    name: "",
    email: "",
    password: "",
    role: "PATIENT",
  });

  const handleSubmit = (e) => {
    e.preventDefault();

    if (isLogin) {
      const user = {
        name: "Mithilesh",
        email: form.email,
        role: "PATIENT",
        token: "dummy-token",
      };

      localStorage.setItem("user", JSON.stringify(user));
      alert("Login Successful");
    } else {
      alert(`Registered as ${form.role}`);
      setIsLogin(true);
    }
  };

  return (
    <div style={styles.page}>
      <div style={styles.card}>
        <h2 style={styles.title}>
          {isLogin ? "Welcome Back 👋" : "Create Account"}
        </h2>

        {/* Toggle */}
        <div style={styles.toggle}>
          <div
            style={isLogin ? styles.activeTab : styles.tab}
            onClick={() => setIsLogin(true)}
          >
            Sign In
          </div>
          <div
            style={!isLogin ? styles.activeTab : styles.tab}
            onClick={() => setIsLogin(false)}
          >
            Sign Up
          </div>
        </div>

        <form onSubmit={handleSubmit} style={styles.form}>
          {!isLogin && (
            <input
              style={styles.input}
              placeholder="Full Name"
              onChange={(e) =>
                setForm({ ...form, name: e.target.value })
              }
            />
          )}

          <input
            style={styles.input}
            placeholder="Email Address"
            onChange={(e) =>
              setForm({ ...form, email: e.target.value })
            }
          />

          <input
            style={styles.input}
            type="password"
            placeholder="Password"
            onChange={(e) =>
              setForm({ ...form, password: e.target.value })
            }
          />

          {!isLogin && (
            <select
              style={styles.input}
              value={form.role}
              onChange={(e) =>
                setForm({ ...form, role: e.target.value })
              }
            >
              <option value="PATIENT">Patient</option>
              <option value="DOCTOR">Doctor</option>
              <option value="ADMIN">Admin</option>
            </select>
          )}

          <button style={styles.button}>
            {isLogin ? "Login" : "Register"}
          </button>
        </form>
      </div>
    </div>
  );
}

const styles = {
  page: {
    height: "100vh",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    background: "linear-gradient(135deg, #1976d2, #42a5f5)",
  },
  card: {
    width: "350px",
    padding: "30px",
    borderRadius: "15px",
    background: "#fff",
    boxShadow: "0 10px 25px rgba(0,0,0,0.2)",
    textAlign: "center",
  },
  title: {
    marginBottom: "20px",
  },
  toggle: {
    display: "flex",
    background: "#f1f1f1",
    borderRadius: "8px",
    marginBottom: "20px",
    overflow: "hidden",
  },
  tab: {
    flex: 1,
    padding: "10px",
    cursor: "pointer",
    color: "#555",
  },
  activeTab: {
    flex: 1,
    padding: "10px",
    background: "#1976d2",
    color: "#fff",
    fontWeight: "bold",
  },
  form: {
    display: "flex",
    flexDirection: "column",
    gap: "12px",
  },
  input: {
    padding: "10px",
    borderRadius: "8px",
    border: "1px solid #ddd",
    outline: "none",
  },
  button: {
    marginTop: "10px",
    padding: "12px",
    borderRadius: "8px",
    border: "none",
    background: "#1976d2",
    color: "#fff",
    fontWeight: "bold",
    cursor: "pointer",
  },
};

export default Login;
